import React from 'react';

const highlights = [
  { icon: '🏥', title: 'Healthcare Technology', desc: 'Platform development & medical record systems' },
  { icon: '⚡', title: 'Full-Stack Development', desc: 'React frontends + Node.js APIs + mobile apps' },
  { icon: '🔒', title: 'Enterprise Systems', desc: 'Auth, RBAC, dashboards & analytics' },
  { icon: '📡', title: 'API Architecture', desc: 'RESTful APIs, integrations & microservices' },
  { icon: '📱', title: 'Mobile Development', desc: 'Cross-platform Flutter apps with Firebase' },
];

export default function About() {
  return (
    <section id="about">
      <div className="section-inner">
        <div className="section-label">// 01 — about</div>
        <h2 className="section-title">Who I <span>Am</span></h2>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '4rem', alignItems: 'start' }}>
          {/* Left — text */}
          <div>
            {[
              <>I'm <strong style={{ color: 'var(--text)' }}>Bisrat Amare</strong>, an experienced Full-Stack Software Engineer based in Ethiopia with a passion for building scalable, enterprise-grade digital solutions that solve real problems.</>,
              <>With deep expertise in <strong style={{ color: 'var(--text)' }}>React.js, Node.js, Flutter</strong>, and cloud platforms, I specialize in architecting systems that handle complex business logic — from healthcare referral platforms to real-time communication systems.</>,
              <>I bring a <strong style={{ color: 'var(--text)' }}>product-minded engineering approach</strong> — thinking about the user, the business, and the technical architecture all at once. Whether you need a fast-loading frontend, a solid API backend, or a mobile-first experience, I deliver production-ready code.</>,
            ].map((text, i) => (
              <p key={i} style={{ color: 'var(--muted)', marginBottom: '1rem', lineHeight: 1.8, fontSize: '0.95rem' }}>
                {text}
              </p>
            ))}

            <div style={{ display: 'flex', gap: '2rem', marginTop: '2rem' }}>
              {[
                { num: '5+', label: 'Years Experience' },
                { num: '20+', label: 'Projects Delivered' },
                { num: '13+', label: 'Technologies' },
              ].map(s => (
                <div key={s.label}>
                  <div style={{ fontSize: '2rem', fontWeight: 800, color: 'var(--orange)', lineHeight: 1 }}>{s.num}</div>
                  <div style={{ fontSize: '0.7rem', color: 'var(--muted)', letterSpacing: '0.08em', textTransform: 'uppercase', marginTop: 4 }}>{s.label}</div>
                </div>
              ))}
            </div>
          </div>

          {/* Right — highlights */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            {highlights.map(h => (
              <div key={h.title} style={{
                display: 'flex', alignItems: 'center', gap: '1rem',
                background: 'var(--surface)', border: '1px solid var(--border)',
                borderRadius: 8, padding: '1rem 1.25rem',
                transition: 'border-color 0.2s'
              }}
              onMouseEnter={e => e.currentTarget.style.borderColor = 'rgba(255,107,26,0.4)'}
              onMouseLeave={e => e.currentTarget.style.borderColor = 'var(--border)'}>
                <div style={{
                  width: 36, height: 36, borderRadius: 6,
                  background: 'rgba(255,107,26,0.12)',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: '1.1rem', flexShrink: 0
                }}>{h.icon}</div>
                <div>
                  <div style={{ fontWeight: 700, fontSize: '0.9rem', marginBottom: 2 }}>{h.title}</div>
                  <div style={{ color: 'var(--muted)', fontSize: '0.82rem' }}>{h.desc}</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
